#include <iostream>
#include <string>
#include <cctype>
#include <cmath>

int main() {
    // 1. Control flow & math functions
    int exponent = 3;
    double base = 2.0;
    double powerResult = std::pow(base, exponent);

    // 2. Multidimensional array
    int matrix[2][2] = {{1, 2}, {3, 4}};
    int sum = 0;
    for (int r = 0; r < 2; ++r) {
        for (int c = 0; c < 2; ++c) {
            sum += matrix[r][c];
        }
    }

    // 3. Dynamic memory allocation
    int* dynamicArr = new int[3];
    dynamicArr[0] = 10;
    dynamicArr[1] = 20;
    dynamicArr[2] = 30;
    int dynamicVal = dynamicArr[1];
    delete[] dynamicArr;
    dynamicArr = nullptr;

    // 4. Character functions and std::string
    std::string text = "cpp";
    for (char& ch : text) {
        if (std::islower(static_cast<unsigned char>(ch))) {
            ch = static_cast<char>(std::toupper(static_cast<unsigned char>(ch)));
        }
    }
    text.append("3e");
    std::string sub = text.substr(0, 3);

    // Deterministic stdout
    std::cout << "pow(2, 3) = " << powerResult << "\n";
    std::cout << "matrix sum = " << sum << "\n";
    std::cout << "dynamicArr[1] = " << dynamicVal << "\n";
    std::cout << "transformed text = " << text << "\n";
    std::cout << "substring = " << sub << "\n";

    return 0;
}
